    //   t > simionDepart - tb  =>  t + tb > simionDepart  (bus hasn't arrived at A yet when Simion leaves)
    //   t < simionArrive       =>  bus has left B before Simion arrives at B

    // So we just need to count integers t such that:
    //   simionDepart - tb < t < simionArrive
    //   AND t is a valid departure time for a bus from B.

    // Valid departure times for buses from B:
    //   t = 300 + k * b, for k = 0, 1, 2, ...
    //   AND t <= 1439 (11:59 PM)

    // Let's find the range of k.
    //   300 + k * b > simionDepart - tb
    //   300 + k * b < simionArrive
    //   300 + k * b <= 1439

    const firstBusTime = 300; // 05:00
    const lastBusTime = 1439; // 23:59

    let count = 0;

    // Find the smallest k such that 300 + k*b > simionDepart - tb
    // k > (simionDepart - tb - 300) / b
    // k_min = floor((simionDepart - tb - 300) / b) + 1

    // Find the largest k such that 300 + k*b < simionArrive
    // k < (simionArrive - 300) / b
    // k_max = ceil((simionArrive - 300) / b) - 1

    // Also need 300 + k*b <= 1439
    // k <= (1439 - 300) / b

    const minK = Math.floor((simionDepart - tb - firstBusTime) / b) + 1;
    const maxK1 = Math.ceil((simionArrive - firstBusTime) / b) - 1;
    const maxK2 = Math.floor((lastBusTime - firstBusTime) / b);
    const maxK = Math.min(maxK1, maxK2);

    if (minK <= maxK) {
        count = maxK - minK + 1;
    }

