    const timeStr = lines[2].trim();

    const a = line1[0];
    const ta = line1[1];
    const b = line2[0];
    const tb = line2[1];

    // Parse departure time
    const [hh, mm] = timeStr.split(':').map(Number);
    const simionDeparture = hh * 60 + mm;
    const simionArrival = simionDeparture + ta;

    // Buses from B depart every b minutes, starting at 05:00 (300 minutes)
    // A bus from B that departs at time t (minutes from midnight) arrives at A at t + tb
    // Simion is on the road from simionDeparture to simionArrival
    // He meets a bus from B if:
    // - The bus departs from B at time t
    // - The bus is on the road when Simion is on the road
    // - They meet strictly between A and B (not at endpoints)

    // A bus from B departing at time t is on the road from t to t + tb
    // Simion is on the road from simionDeparture to simionArrival
    // They overlap if: t < simionArrival AND t + tb > simionDeparture
    // i.e., t < simionArrival AND t > simionDeparture - tb

    // But we also need to exclude meetings at the start and finish.
    // Meeting at start (city A): This would happen if the bus arrives at A exactly when Simion departs.
    //   Bus arrives at A at t + tb. If t + tb == simionDeparture, they meet at A. Exclude.
    //   So t + tb > simionDeparture (strictly)

    // Meeting at finish (city B): This would happen if the bus departs from B exactly when Simion arrives.
    //   Bus departs at t. If t == simionArrival, they meet at B. Exclude.
    //   So t < simionArrival (strictly)

    // So the condition is: simionDeparture - tb < t < simionArrival
    // And t must be a valid departure time from B: t >= 300 (05:00) and t <= 23*60+59 (23:59)
    // Also, buses depart at 300, 300+b, 300+2b, ...

    // Find the range of t values
    const minT = Math.max(300, Math.floor(simionDeparture - tb) + 1); // t > simionDeparture - tb, so t >= floor(simionDeparture - tb) + 1
    const maxT = Math.min(23 * 60 + 59, simionArrival - 1); // t < simionArrival, so t <= simionArrival - 1

    let count = 0;
    // Buses depart at 300, 300+b, 300+2b, ...
    // Find the first bus departure >= minT
    if (minT <= maxT) {
        // First bus at or after minT
        let firstBus = 300;
        if (firstBus < minT) {
            const k = Math.ceil((minT - 300) / b);
            firstBus = 300 + k * b;
        }

        // Count buses from firstBus to maxT with step b
        if (firstBus <= maxT) {
            count = Math.floor((maxT - firstBus) / b) + 1;
        }
    }

