```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const [a, ta] = lines[0].split(' ').map(Number);
    const [b, tb] = lines[1].split(' ').map(Number);
    const timeStr = lines[2].trim();

    const [hh, mm] = timeStr.split(':').map(Number);
    const simionDeparture = hh * 60 + mm;
    const simionArrival = simionDeparture + ta;

    // Buses from B to A depart every b minutes starting from 05:00 (300 minutes)
    // A bus from B that departs at time t (in minutes from 00:00) will be on the road
    // during the interval [t, t + tb].
    // Simion is on the road during [simionDeparture, simionArrival].
    // They meet if the intervals overlap, but NOT at the endpoints (start and finish).
    // So we need: t < simionArrival AND t + tb > simionDeparture
    // Which means: simionDeparture - tb < t < simionArrival

    // Buses from B depart at times: 300, 300+b, 300+2b, ... up to 23*60+59 = 1439
    // But the last bus departs not later than 11:59 PM (23:59)

    let count = 0;
    const firstBusB = 5 * 60; // 05:00 = 300 minutes
    const lastBusB = 23 * 60 + 59; // 23:59 = 1439 minutes

    // Find the first bus from B that departs after (simionDeparture - tb)
    // and before simionArrival
    // t must satisfy: simionDeparture - tb < t < simionArrival
    // and t = 300 + k*b for some integer k >= 0
    // and t <= 1439

    const lowerBound = simionDeparture - tb; // t must be > lowerBound
    const upperBound = simionArrival; // t must be < upperBound

    // Find smallest k such that 300 + k*b > lowerBound
    // k*b > lowerBound - 300
    // k > (lowerBound - 300) / b
    // k_min = floor((lowerBound - 300) / b) + 1, but if (lowerBound - 300) is negative, k_min could be 0 or negative

    let kMin = 0;
    if (lowerBound >= firstBusB) {
        // Need 300 + k*b > lowerBound => k*b > lowerBound - 300
        // k > (lowerBound - 300) / b
        kMin = Math.floor((lowerBound - firstBusB) / b) + 1;
    } else {
        // lowerBound < 300, so any k >= 0 works for the lower bound
        kMin = 0;
    }

    // Find largest k such that 300 + k*b < upperBound
    // k*b < upperBound - 300
    // k < (upperBound - 300) / b
    // k_max = ceil((upperBound - 300) / b) - 1
    // Or more precisely: k*b < upperBound - 300
    // If upperBound - 300 <= 0, no buses
    let kMax = -1;
    if (upperBound > firstBusB) {
        // k*b < upperBound - 300
        // k < (upperBound - 300) / b
        // k_max = floor((upperBound - 300 - 1) / b) if we want strict inequality
        // Actually: k*b < X means k <= floor((X-1)/b) for integer k
        // Let X = upperBound - 300
        // We need k*b < X
        // k < X/b
        // k_max = ceil(X/b) - 1
        // Or: k_max = Math.floor((X - 1) / b) if X > 0
        const X = upperBound - firstBusB;
        if (X > 0) {
            kMax = Math.ceil(X / b) - 1;
        }
    }

    // Also constrain kMax so that departure time <= 1439
    // 300 + kMax*b <= 1439 => kMax <= (1439 - 300) / b = 1139 / b
    const kMaxLimit = Math.floor((lastBusB - firstBusB) / b);
    kMax = Math.min(kMax, kMaxLimit);

    if (kMax >= kMin && kMin >= 0) {
        count = kMax - kMin + 1;
    }

    console.log(count);
});
